/** static s32 FirstBattleTrainerIdToRematchTableId(const struct RematchTrainer *table, u16 trainerId) */
export function FirstBattleTrainerIdToRematchTableId(table: any, trainerId: any): any {
  let i: any = null;

      for (i = 0; i < REMATCH_TABLE_ENTRIES; i++)
      {
          if (table[i].trainerIds[0] == trainerId)
              return i;
      }

      return -1;
}

/** static s32 TrainerIdToRematchTableId(const struct RematchTrainer *table, u16 trainerId) */
export function TrainerIdToRematchTableId(table: any, trainerId: any): any {
  let i, j;

      for (i = 0; i < REMATCH_TABLE_ENTRIES; i++)
      {
          for (j = 0; j < (5); j++)
          {
              if (table[i].trainerIds[j] == 0) break;  
              if (table[i].trainerIds[j] == trainerId)
                  return i;
          }
      }

      return -1;
}

/** static bool32 IsRematchForbidden(s32 rematchTableId) */
export function IsRematchForbidden(rematchTableId: any): any {
  if (rematchTableId >= (REMATCH_SIDNEY))
          return TRUE;
      else if (rematchTableId == REMATCH_WALLY_VR)
          return !FlagGet((0x7E));
      else
          return FALSE;
}

/** static void SetRematchIdForTrainer(const struct RematchTrainer *table, u32 tableId) */
export function SetRematchIdForTrainer(table: any, tableId: any): any {
  let i: any = null;

      for (i = 1; i < (5); i++)
      {
          let trainerId: any = table[tableId].trainerIds[i];

          if (trainerId == 0)
              break;
          if (!HasTrainerBeenFought(trainerId))
              break;
      }

      gSaveBlock1Ptr.trainerRematches[tableId] = i;
}

/** static bool32 UpdateRandomTrainerRematches(const struct RematchTrainer *table, u16 mapGroup, u16 mapNum) */
export function UpdateRandomTrainerRematches(table: any, mapGroup: any, mapNum: any): any {
  let i: any = null;
      let ret: any = FALSE;

      for (i = 0; i <= (REMATCH_WALLY_VR); i++)
      {
          if (table[i].mapGroup == mapGroup && table[i].mapNum == mapNum && !IsRematchForbidden(i))
          {
              if (gSaveBlock1Ptr.trainerRematches[i] != 0)
              {
                   
                  ret = TRUE;
              }
              else if (FlagGet((0x15C) + i)
               && (Random() % 100) <= 30)   
              {
                  SetRematchIdForTrainer(table, i);
                  ret = TRUE;
              }
          }
      }

      return ret;
}

